WITH sales_agg AS ( SELECT sm.sm_ship_mode_id AS ship_mode, ib.ib_income_band_sk AS income_band, sum(cs.cs_ext_sales_price) AS total_sales, sum(cs.cs_net_profit) AS total_profit, count(distinct cs.cs_order_number) AS order_cnt, max(concat(c.c_first_name, ' ', c.c_last_name)) AS sample_customer, max(substring(c.c_last_name, 1, 3)) AS last_name_prefix FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE regexp_like(ca.ca_street_type, '(?i)street|road|drive') AND ca.ca_location_type LIKE 'apartment%' AND regexp_like(c.c_email_address, '@gmail\\.com$') GROUP BY ROLLUP(sm.sm_ship_mode_id, ib.ib_income_band_sk) ) SELECT ship_mode, income_band, total_sales, total_profit, order_cnt, sample_customer, last_name_prefix, sum(total_sales) OVER (ORDER BY ship_mode, income_band ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total_sales, lag(total_sales) OVER (ORDER BY ship_mode, income_band) AS prev_total_sales FROM sales_agg ORDER BY ship_mode ASC NULLS LAST, income_band ASC NULLS LAST LIMIT 100
